// Lê o webhook do Chatwoot (evento message_created) e devolve só o que o agente precisa.
const b = $json.body || $json;
const conv = b.conversation || {};
const msg0 = (conv.messages && conv.messages[0]) || {};
const sender = b.sender || msg0.sender || (conv.meta && conv.meta.sender) || {};
const anexo = (b.attachments && b.attachments[0]) || (msg0.attachments && msg0.attachments[0]) || null;
const tipoEntrada = String(b.message_type ?? msg0.message_type ?? '');
const recebida = tipoEntrada === 'incoming' || tipoEntrada === '0';
// Telefone no padrão do CRM: 55 + DDD + 9 + número (a Meta às vezes manda sem o nono dígito)
let d = String(sender.phone_number || '').replace(/\D/g, '');
if (d.length === 12 && d.startsWith('55') && /[6-9]/.test(d[4])) d = d.slice(0, 4) + '9' + d.slice(4);
const caixaEsperada = String($('Canal').first().json.chatwoot_inbox_id || '');
const caixa = String((b.inbox && b.inbox.id) || conv.inbox_id || '');
return { json: {
  valida: recebida && !b.private && (b.event ? b.event === 'message_created' : true) && d.length >= 12 && (!caixaEsperada || caixaEsperada === caixa),
  telefone: d,
  chat_id: String(conv.id || b.conversation_id || ''),
  content: b.content || msg0.content || '',
  content_type: anexo ? String(anexo.file_type || 'file') : 'text',
  content_url: anexo ? (anexo.data_url || '') : '',
  nome_contato: sender.name || '',
  message_id: String(b.id || msg0.id || '')
} };
